    filterProcessStatus: function (chk, load) {
        // 1   Aguardando empacotamento
        // 2   Aguardando finalização de dependência
        // 3   Empacotado e aguardando envio
        // 4   Enviado e aguardando processamento
        // 5: "Dependência não satisfeita",
        // 201 Sucesso
        // 202 Sucesso com advertência
        // 210 Sucesso informado localment
        // 301 Erro Servidor
        // 401 Erro no conteúdo do evento
        // 402 Schema inválido
        // 403 Leiaute inválido
        // 404 Erro do certificado digital
        // 405 Erro na assinatura evento
        // 406 Evento não pertence ao grupo
        // 407 Regra de precedência de eventos não seguida
        // 408 Erro na integração com o sistema CNPJ / CPF
        // 409 Erro na integração - Procuração Eletrônica RFB
        // 410 Erro na integração - Procuração Eletrônica Caixa
        // 411 Assinante inválido
        this._filterProcessStatus = core.nullValue(
            this._filterProcessStatus,
            this.initialProcessStatus
        );

        if(chk != undefined){
            if (chk.checked)
                this._filterProcessStatus.push(chk.value);
            else
                this._filterProcessStatus.remove(chk.value);
        }

        if (this.canLoad)
            this.setFilterProperty("process_status__in", this._filterProcessStatus, 1000, load);
    },

    filterXmlInvalid: function (chk, load) {
        if (chk != undefined && this.canLoad){
            if (!chk.checked) this.setFilterProperty("xsd_schema_validated", false, 1010, load);
            else this.removeFilterProperty("xsd_schema_validated", 1010, load);
        }
    },

    filterArchiveds: function (archived, load) {
        if (this.canLoad){
            if(archived === null)
                this.removeFilterProperty("archived", 1020, load);
            else
                this.setFilterProperty("archived", archived, 1020, load);
        }
    },

    filterValids: function (chk, load) {
        if (chk != undefined && this.canLoad){
            if (!chk.checked) {
                this.setFilterProperty("has_exclusion_cache", false, 1031, false);
                this.setFilterProperty("is_invalid_cache", false, 1032, load);
            } else {
                this.removeFilterProperty("has_exclusion_cache", 1031, false);
                this.removeFilterProperty("is_invalid_cache", 1032, load);
            }
        }
    },

    filterAction: function (chk, status, load) {
        this._filterAction = core.nullValue(this._filterAction, []);
        var self = this;
        if (chk != undefined){
            if (!chk.checked)
                status.forEach(function (el) { self._filterAction.push(el); });
            else
                status.forEach(function (el) { self._filterAction.remove(el); })
        }
        if (this.canLoad){
            if (this._filterAction.length === 0)
                this.removeFilterProperty("action__in", 1040, load);
            else
                this.setFilterProperty("action__in", this._filterAction, 1040, load);
        }
    },

    filterAcronym: function (chk, status, load) {
        this._filterAcronym = core.nullValue(this._filterAcronym, []);
        var self = this;
        if (chk != undefined){
            if (!chk.checked)
                status.forEach(function (el) { self._filterAcronym.push(el); });
            else
                status.forEach(function (el) { self._filterAcronym.remove(el); })
        }
        if (this.canLoad){
            if (this._filterAcronym.length === 0)
                this.removeFilterProperty("acronym__in", 1041, load);
            else
                this.setFilterProperty("acronym__in", this._filterAcronym, 1041, load);
        }
    },

    filterOccurrence: function (){
        var wnd = Ext._create('Ext.Window', {
            title: 'Selecionar ocorrência',
            modal: true,
            width: 600,
            border: false,
            buttons: [
                {
                    text: 'Selecionar',
                    scope: this,
                    handler: function () {
                        var form = wnd.getComponent(0).getForm();
                        occurrence = form.findField('occurrence').getValue()
                        if (occurrence)
                            this.setFilterProperty('results__ocurrences__code', occurrence, 1012);
                        else
                            this.removeFilterProperty('results__ocurrences__code', 1012);
                        wnd.destroy();
                    }
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function () {
                        wnd.destroy();
                    }
                }
            ],
            items: Ext._create('Ext.form.FormPanel', {
                frame: true,
                items: [
                    {
                        xtype: "combo",
                        fieldLabel: "Ocorrência",
                        width: 450,
                        allowBlank: false,
                        name: "occurrence",
                        emptyText: 'Selecione o código da ocorrência',
                        store: new Ext.data.JsonStore({
                            fields: ['pk', 'desc'],
                            root: 'root',
                            proxy: new Ext.data.HttpProxy({
                                url: toolkit.util.Normalize.controller_action('ESOCIALEvent', 'occurrences_list'),
                                method: 'GET'
                            }),
                            autoLoad: true
                        }),
                        displayField: 'desc',
                        valueField: 'pk',
                        mode: 'local',
                        resizable: true,
                        editable: false,
                        triggerAction: 'all'
                    },
                ]
            })
        }).show();
    },
