Ext._define('esocial.itemtable.ItemGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'esocial.itemtable.ItemWindow',

    rest: 'esocial.itemtable.ItemRestful',

    configOrderToolBar: ['add', 'edit', 'remove', 'search', '->', 'filterTable', 'download'],

    // actionColumnWidth: 120,
    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    { header: 'Chave', dataIndex: 'pk', width: 50, hidden: false },
                    // { header: '', dataIndex: 'icons', width: 95, menuDisabled: true, renderer: toolkit.util.formatStatus },
                    { header: 'Codigo', dataIndex: 'code', width: 90, hidden: false },
                    { header: 'Info', dataIndex: 'info', width: 90, hidden: false },
                    { header: 'Titulo', dataIndex: 'title', width: 400, hidden: false },
                    { header: 'Descrição', dataIndex: 'description', id: 'autoExpandColumn' },
                    { header: 'Tabela e-Social', dataIndex: 'esocial_table', width: 50 },
                    { header: 'Opção', dataIndex: 'choice_unicode', width: 100 },
                    { header: 'Início vigência', dataIndex: 'start_validity', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y') },
                    { header: 'Fim vigência', dataIndex: 'end_validity', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y') },
                    { header: 'Moficado em', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true },
                    { header: 'Moficado por', dataIndex: 'modified_by_unicode', width: 120, hidden: true },
                    { header: 'Criado em', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true },
                    { header: 'Criado por', dataIndex: 'created_by_unicode', width: 120, hidden: true },
                ]
            );

        return this._columnModel;
    },

    getConfigActionsItems: function(cfg){
        var menu = esocial.itemtable.ItemGrid.superclass.getConfigActionsItems.call(this, cfg);

        menu['filterTable'] = {
            xtype: 'combo',
            emptyText: 'Filtrar por tabela',
            width: 180,
            store: new Ext.data.JsonStore({
                fields: ['pk', 'desc'],
                root: 'root',
                proxy: new Ext.data.HttpProxy({
                    url: toolkit.util.Normalize.controller_action('ESOCIALItemTable', 'table_list'),
                    method: 'GET'
                }),
                autoLoad: true
            }),

            displayField: 'desc',
            valueField: 'pk',
            triggerAction: 'all',
            editable: false,
            listeners: {
                scope: this,
                select: function(combo, record, index) {
                    var store = this.getStore();

                    if(record.get('pk') == 0)
                        this.removeFilterProperty('esocial_table', 1000);
                    else this.setFilterProperty("esocial_table", record.get('pk'), 1000);

                    store.load({});
                }
            }
        };
        return menu;
    },

    _updateRow: function (idx, pk) {
        var selRec = this.getSelectionModel().getSelected()
        if (selRec && selRec.data.pk != pk)
            this.getSelectionModel().deselectRow(idx);
        this.getStore().load({
            params: this.getStore().lastOptions.params,
            callback: function (r, opt, success) {
                var newRec = this.getStore().getAt(idx);
                if (pk && pk == newRec.get('pk'))
                    this.getSelectionModel().selectRow(idx);
            },
            scope: this
        });
    },

    executeAction: function (action, id, idx, msg, callback) {
        var vId = id, vIdx = idx;
        var rMask = new Ext.LoadMask(this.ownerCt.getEl(), { msg: msg ? msg : "Aguarde..." });
        rMask.show();
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action('ESOCIALItemTable', action),
            params: { id: id },
            success: function (request) {
                var obj = Ext.decode(request.responseText);
                rMask.hide();
                if (!obj.success) {
                    Ext.MessageBox.show({
                        title: 'Erro',
                        msg: obj.message,
                        buttons: Ext.MessageBox.OK,
                        icon: Ext.MessageBox.ERROR
                    })
                } else {
                    if (obj.instance) {
                        this._updateRow(vIdx, obj.instance.pk);
                    }
                    if (!callback) {
                        Ext.MessageBox.show({
                            title: 'Informação',
                            msg: obj.message,
                            buttons: Ext.MessageBox.OK,
                            icon: Ext.MessageBox.INFO
                        });
                    } else {
                        callback(obj);
                    }
                }

            },
            failure: function () {
                rMask.hide();
                Ext.MessageBox.show({
                    title: 'Erro',
                    msg: 'Ocorreu um erro inesperado',
                    buttons: Ext.MessageBox.OK,
                    icon: Ext.MessageBox.ERROR
                });
            },
            scope: this,
        });
    },

});

