    discouver: function(){
        Ext.Msg.confirm(
            'Confirmação',
            'Deseja confirmar a atualização da lista de pessoas qualificáveis?',
            function(btn)
            {
                if(btn == 'yes')
                {
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('ESCRegistrationQualification', 'discouver'),
                        // 'params': {
                        //     'solicitacao': id_solicitacao
                        // },
                        scope: this,
                        callback: function() {

                        },
                        success: function(request) {
                            var obj = Ext.decode(request.responseText);
                            if(!obj.success)
                                Ext.Msg.show({
                                    title: this.title,
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: obj.message
                                });
                            else
                                this.reload();
                        },
                        failure: function(request) {
                            Ext.Msg.show({
                                'title': this.title,
                                'icon': Ext.Msg.ERROR,
                                'buttons': Ext.Msg.OK,
                                'msg': 'O recurso não esta disponivel no momento, tente novamente mais tarde.'
                            });
                        }
                    });
                }
            }
        );
    },

