/*
 * src: /app/root/esocial/static/payrollperiod/PayrollPeriodManage.js
 */
/** autogenerated **/
Ext._define('esocial.payrollperiod.PayrollPeriodManage', {
    extend: 'toolkit.widget.TabPanel',

    getPayrollPeriodGrid: function (cfg) {
        if (!this._gridPayrollPeriod)
            this._gridPayrollPeriod = Ext._create('esocial.payrollperiod.Grid', {
                region: 'center',
                gridAutoLoad: true,
                split: true,
            });

        this._gridPayrollPeriod.getSelectionModel().on({
            scope: this,
            rowselect: function (sm, index, record) {
                this.observer(record.get('pk'));
            },
            rowdeselect: function (sm) {
                this.observer(null);
            }
        });

        this._gridPayrollPeriod.getStore().on({
            scope: this,
            load: function () {
                var selected = this._gridPayrollPeriod.getSelectionModel().getSelected();
                if (selected) this.observer(selected.get("pk"));
                else this.observer(null);
            }
        });
        return this._gridPayrollPeriod;
    },

    getPendencyPeriodGrid: function (cfg) {
        if (!this._pendencyPeriodGrid)
            this._pendencyPeriodGrid = Ext._create('esocial.payrollperiod.PendencyPeriodGrid', {
                title: 'Pendências',
                region: 'south',
                height: 500,
                gridAutoLoad: false
            });

        return this._pendencyPeriodGrid;
    },

    observer: function (payrollPeriod, prevent) {
        prevent = core.nullValue(prevent, false);

        if (payrollPeriod !== undefined) {
            this.payrollPeriod = payrollPeriod;

            !prevent && this.observePayrollPeriod();
        }

        return this.payrollPeriod;
    },

    observePayrollPeriod: function () {
        var value = this.observer();

        if (value) {
            this.getPendencyPeriodGrid().setParam('payroll_period', value);
            this.getPendencyPeriodGrid().setFilterProperty('payroll_period', value, 1);
            this.getPendencyPeriodGrid().enable();
        }
        else{
            this.getPendencyPeriodGrid().setParam('payroll_period', 0);
            this.getPendencyPeriodGrid().setFilterProperty('payroll_period', 0, 1);
            this.getPendencyPeriodGrid().getStore().removeAll();
            this.getPendencyPeriodGrid().disable();
        }
    },

    getTbTextItem: function(cfg){
        if (!this._tbProcessTextItem) {
            this._tbProcessTextItem = Ext._create("Ext.Toolbar.TextItem", {
                text: "AMBIENTE LIBERADO",
                style: {"color": "#14950E", "font-weight": "bold" }
            });
        }

        return this._tbProcessTextItem;
    },

    getProcessEsocial: function () {

        Ext.Ajax.request({
            url: core.callAction('ESOCIALBatchEvent', 'active_process'),
            params: {},
            method: 'GET',
            scope: this,
            success: function (xhr) {
                var rst = Ext.decode(xhr.responseText);
                var tbItem = this.getTbTextItem();

                if (rst.success) {
                    if (rst.processing) {
                        tbItem.setText('AMBIENTE EM PROCESSAMENTO - AGUARDE - ' + rst.message);
                        tbItem.getEl().setStyle('color', '#F00');
                    } else {
                        tbItem.setText('AMBIENTE LIBERADO');
                        tbItem.getEl().setStyle('color', '#14950E');
                    }
                }
            },
            failure: function () {
                console.info(this);
            }
        });
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Períodos (Folhas) eSocial',
            }
        );

        var style = { "color": "#14950E", "font-weight": "bold" };
        var value = "AMBIENTE DE PRODUÇÃO DO ESOCIAL";
        if (cfg.environment == 2){
            style = { color: "#15428B", "font-weight": "bold" };
            value = "HOMOLOGAÇÃO ESOCIAL - PRODUÇÃO RESTRITA";
        }


        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getPayrollPeriodGrid(cfg),
                    this.getPendencyPeriodGrid(cfg),
                ],
                fbar: {
                    style: {"font-weight": "bold", "margin": "0", "padding": "0" },
                    buttonAlign: "left",
                    scope: this,
                    items: [{
                            xtype: 'tbtext',
                            style: style,
                            text: value
                        },
                        '->',
                        this.getTbTextItem()
                    ],

                },
            }
        );

        esocial.payrollperiod.PayrollPeriodManage.superclass.constructor.call(this, cfg);

        // Start a simple clock task that updates a div once per second
        this._taskProcessing = {
            scope: this,
            run: this.getProcessEsocial,
            interval: 5000 //1 second
        }
        Ext.TaskMgr.start(this._taskProcessing);
    }
});

